import{_ as t}from"./chunks/project-12.DiVlmEh-.js";import{_ as s,c as r,o as i,ag as n}from"./chunks/framework.DX2MDgaT.js";const m=JSON.parse('{"title":"GitHub Projects","description":"","frontmatter":{},"headers":[],"relativePath":"ressources/github-project.md","filePath":"ressources/github-project.md"}'),o={name:"ressources/github-project.md"};function l(a,e,u,c,p,d){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="github-projects" tabindex="-1">GitHub Projects <a class="header-anchor" href="#github-projects" aria-label="Permalink to &quot;GitHub Projects&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title"><a href="./github-project-guide.html">Voir le guide technique pour la création de votre projet</a></p></div><p>GitHub Projects est un outil de gestion de projet visuel intégré directement à GitHub.<br> Il permet aux équipes de suivre l’avancement des tâches et d’organiser le développement en lien direct avec les <strong>issues</strong> et les <strong>pull requests</strong>.</p><p>GitHub Projects est particulièrement adapté pour :</p><ul><li>Organiser les tâches et fonctionnalités d’un projet</li><li>Suivre les sprints en développement Agile</li><li>Faciliter la collaboration en équipe</li><li>Visualiser l’avancement du projet en un coup d’œil</li><li>Lier les tâches directement au code (issues, branches, PR)</li></ul><hr><h2 id="les-composants-cles-de-github-projects" tabindex="-1">Les Composants Clés de GitHub Projects <a class="header-anchor" href="#les-composants-cles-de-github-projects" aria-label="Permalink to &quot;Les Composants Clés de GitHub Projects&quot;">​</a></h2><h3 id="tableaux-projects" tabindex="-1">Tableaux (Projects) <a class="header-anchor" href="#tableaux-projects" aria-label="Permalink to &quot;Tableaux (Projects)&quot;">​</a></h3><p>Un <strong>Project</strong> représente un projet entier ou un volet de développement.<br> Il peut être associé à un dépôt GitHub ou être indépendant (projet global).</p><p><img src="'+t+'" alt="Éditer un récit"></p><hr><h3 id="colonnes-lists-status" tabindex="-1">Colonnes (Lists / Status) <a class="header-anchor" href="#colonnes-lists-status" aria-label="Permalink to &quot;Colonnes (Lists / Status)&quot;">​</a></h3><p>Les colonnes permettent de structurer le travail en étapes ou en catégories.<br> Exemple typique de workflow pour un projet de ce cours :</p><ul><li><strong>Backlog</strong> : contient tous les récits utilisateurs ou idées de fonctionnalités.</li><li><strong>À faire</strong> : contient les tâches sélectionnées pour le sprint.</li><li><strong>En cours</strong> : contient les tâches en cours de réalisation.</li><li><strong>Bogues</strong> : contient les anomalies à corriger.</li><li><strong>Terminée</strong> : contient les tâches finalisées et validées.</li></ul><hr><h3 id="cartes-cards-issues" tabindex="-1">Cartes (Cards / Issues) <a class="header-anchor" href="#cartes-cards-issues" aria-label="Permalink to &quot;Cartes (Cards / Issues)&quot;">​</a></h3><p>Chaque carte correspond généralement à une <strong>issue</strong> GitHub ou à une note libre.<br> On peut y ajouter :</p><ul><li>Une description détaillée</li><li>Une checklist (sous-tâches)</li><li>Une date limite (milestone)</li><li>Des étiquettes (priorité, type de tâche)</li><li>Un responsable (assigné à un membre de l’équipe)</li><li>Des discussions liées (via commentaires ou PR)</li></ul><p><strong>Exemple de carte pour une fonctionnalité :</strong></p><p><strong>Issue : <em>En tant qu’usager, je veux rechercher un livre par titre afin de trouver rapidement un ouvrage qui m’intéresse.</em></strong></p><ul><li><strong>Colonne</strong> : En cours</li><li><strong>Assigné</strong> : Marie</li><li><strong>Description</strong> : Permettre la recherche d’un livre par titre, auteur ou catégorie.</li><li>✅ <strong>Checklist</strong> : <ul><li>[ ] Interface utilisateur pour la recherche</li><li>[ ] Connexion avec la base de données</li><li>[ ] Tests de performance</li></ul></li><li>📅 <strong>Milestone</strong> : Sprint 2</li></ul><hr><h2 id="suivre-l-avancement-des-taches" tabindex="-1">Suivre l’avancement des tâches <a class="header-anchor" href="#suivre-l-avancement-des-taches" aria-label="Permalink to &quot;Suivre l’avancement des tâches&quot;">​</a></h2><ul><li>Les développeurs déplacent les cartes entre les colonnes au fur et à mesure de l’avancement.</li><li>Chaque issue peut être liée à une branche ou une pull request pour assurer le suivi.</li><li>À la fin de chaque sprint, les cartes sont révisées pour confirmer les fonctionnalités livrées et replanifier celles qui ne sont pas terminées.</li></ul>',24)])])}const b=s(o,[["render",l]]);export{m as __pageData,b as default};
